72	template <std::size_t N, typename T, typename L = void>
73	struct LocalVar {
74	    static_assert(!std::is_reference_v<T>, "[ERROR]: [Atvoss][Expression] A LocalVar must not be a reference");
75	    using Type = T;
76	    using RetType = std::decay_t<T>;
77	    using TensorType = RetType;
78	    using Like = L;
79	    static constexpr std::size_t number = N;
80	
81	    template <typename V>
82	    constexpr auto operator=(Expression<V>)
83	    {
84	        static_assert(
85	            Util::AlwaysFalse_v<V>, "[ERROR]: [Atvoss][Expression] Please use Expression<LocalVar> for assignment");
86	    }
87	};
