406	template <typename T, typename U, typename R = typename std::decay_t<T>::RetType>
407	struct BinaryOp : private Util::CompressedPair<T, U> {
408	private:
409	    using Storage = Util::CompressedPair<T, U>;
410	
411	public:
412	    static_assert(
413	        !(std::is_rvalue_reference_v<T> || std::is_rvalue_reference_v<U>),
414	        "[ERROR]: [Atvoss][Expression] Rvalue references cannot be stored");
415	
416	    using IsBinaryOp = void;
417	    using LhsType = T;
418	    using RhsType = U;
419	    using TensorType = typename T::TensorType;
420	    using RetType = R;
421	
422	    BinaryOp() = default;
423	    constexpr BinaryOp(T t, U u) : Storage(t, u)
424	    {}
425	
426	    constexpr const T& GetLhs() const
427	    {
428	        return Storage::First();
429	    }
430	    constexpr const U& GetRhs() const
431	    {
432	        return Storage::Second();
433	    }
434	};
