469	template <typename T>
470	template <typename U>
471	__host_aicore__ constexpr auto Expression<T>::operator=(Expression<U> u)
472	{
473	    static_assert(
474	        (IsParam_v<T> || IsLocalVar_v<T> || std::is_lvalue_reference_v<T>),
475	        "[ERROR]: [Atvoss][Expression] Only a Param, LocalVar, or reference can appear on the left side "
476	        "of assignment");
477	    if constexpr (IsLocalVar_v<U> || IsParam_v<U>) {
478	        constexpr auto result = Atvoss::OpCopy<U>(u.data);
479	        return Expression<OpAssign<T, std::decay_t<decltype(result)>>>{{data, u.data}};
480	    } else {
481	        return Expression<OpAssign<T, U>>{{data, u.data}};
482	    }
483	}
