72	template <size_t N, typename T1>
73	static constexpr inline int32_t GetTotal(uint32_t eleCntInTensor = 1, int defaultSize = 1)
74	{
75	    constexpr size_t tupleSize = T1::size::value;
76	    if constexpr (tupleSize == 0) {
77	        return eleCntInTensor;
78	    } else if constexpr (N > tupleSize) {
79	        return eleCntInTensor;
80	    } else {
81	        using TValueType = typename T1::template get_type<N>;
82	        int32_t TValue = TValueType::value;
83	        defaultSize = defaultSize * TValue;
84	        if constexpr (N < tupleSize - 1) {
85	            return GetTotal<N + 1, T1>(defaultSize);
86	        }
87	        return defaultSize;
88	    }
89	}
