91	/*!
92	 * \brief Calculation layout's total length.
93	 * \param[in] eleCntInTensor, Init-val.
94	 * \param[in] defaultSize, Init-val.
95	 * \return int32_t, Shape's total
96	 */
97	template <size_t N, typename T>
98	static constexpr inline int32_t GetTotalElement(uint32_t eleCntInTensor = 1, int defaultSize = 1)
99	{
100	    using shape = typename T::TileShape;
101	    return GetTotal<N, shape>(eleCntInTensor, defaultSize);
102	}
