104	#if !defined(__ATVOSS_HOST_ONLY__)
105	template <Operation op = Operation::Unary, typename ArgTup>
106	__aicore__ inline static constexpr auto GetShape(ArgTup& args)
107	{
108	    auto blockTensor = atvoss_std::get<0>(args);
109	    using LayoutType = typename decltype(blockTensor)::LayoutType;
110	    if constexpr (std::is_same_v<LayoutType, Atvoss::Layout::VariableRankExtents<1>>) {
111	        if constexpr (op == Operation::Unary) {
112	            return blockTensor.GetLayout().GetUnaryShape();
113	        }
114	        if constexpr (op == Operation::Binary) {
115	            return blockTensor.GetLayout().GetBinaryShape();
116	        }
117	    } else {
118	        if constexpr (op == Operation::Unary) {
119	            return LayoutType::ShapeType::UNARY_SHAPE;
120	        }
121	        if constexpr (op == Operation::Binary) {
122	            return LayoutType::ShapeType::BINARY_SHAPE;
123	        }
124	    }
125	}
126	#endif
