57	/*!
58	 * \brief Broadcast calculation based on the expression
59	 * \param[in] args, LocalTensor data of input tensors & output tensor
60	 * \param[in] localVar, LocalTensor data of temp tensors
61	 * \param[in] tail, Calculate the length of the data
62	 * \return Broadcast Expression calculation
63	 */
64	template <typename T, typename U, Atvoss::Pattern pattern>
65	struct Evaluator<OpAssign<T, OpBroadcast<pattern, U>>> {
66	    using Type = void;
67	
68	    template <typename Context>
69	    __aicore__ inline auto operator()(const OpAssign<T, OpBroadcast<pattern, U>>& op, Context& context) const
70	    {
71	        using Dtype = Dtype_t<T>;
72	        OperationShape operationShape = GetShape<Operation::Binary>(context.argsTensors);
73	        return Atvoss::Tile::BroadcastAssign<OperationShape, pattern, Dtype>(
74	            Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(),
75	            Evaluator<U>{}(op.GetRhs().GetData(), context).GetUbTensor(), operationShape);
76	    }
77	};
