51	// Partial specialization for Param
52	template <std::size_t N, typename T, ParamUsage U, std::size_t R>
53	struct Evaluator<Param<N, T, U, R>> {
54	    using Type = T;
55	
56	    template <typename Context>
57	    __aicore__ inline decltype(auto) operator()(Param<N, T, U, R> /*unused*/, Context& context) const
58	    {
59	        static_assert(N > 0, "[ERROR]: [Atvoss][Tile] Param number starts from 1");
60	        constexpr auto index = N - 1;
61	        using ArgsTensors = decltype(context.argsTensors);
62	        using NthType = typename AscendC::Std::tuple_element<index, std::remove_reference_t<ArgsTensors>>::type;
63	        if constexpr (std::is_same_v<T, NthType> || std::is_same_v<T&, NthType> || std::is_same_v<T&&, NthType>) {
64	            return AscendC::Std::get<index>(context.argsTensors);
65	        } else {
66	            static_assert(
67	                U == ParamUsage::IN, "[ERROR]: [Atvoss][Tile] Only in-parameters allow implicit type conversions");
68	            return static_cast<T>(AscendC::Std::get<index>(context.argsTensors));
69	        }
70	    }
71	};
