153	#else
154	                AscendC::PipeBarrier<PIPE_ALL>();
155	#endif
156	                return;
157	            } else if constexpr (
158	                HasUsage<T>{} && T::usage == Atvoss::ParamUsage::IN ||
159	                T::usage == Atvoss::ParamUsage::IN_OUT) { // in param: need copy in
160	                uint32_t inId = Atvoss::Ele::Tile::GetBufferId<
161	                    typename Context::BuffMaps, T::number, Atvoss::Ele::Tile::BufType::PARAM>(context.pingPong);
162	                context.bufPools.AllocTensor(obj.GetUbTensor(), inId);
163	                return;
164	            } else if constexpr (HasUsage<T>{} && T::usage == Atvoss::ParamUsage::OUT) { // out param
165	                uint32_t outId = Atvoss::Ele::Tile::GetBufferId<
166	                    typename Context::BuffMaps, T::number, Atvoss::Ele::Tile::BufType::PARAM>(context.pingPong);
167	                context.bufPools.AllocTensor(obj.GetUbTensor(), outId);
168	#if _ATVOSS_ARCH35_
169	                AscendC::Mutex::Lock<PIPE_V>(outId);
170	#else
171	                AscendC::PipeBarrier<PIPE_ALL>();
172	#endif
173	                return;
174	            }
175	        }
176	    }
177	};
