11	/*!
12	 * \file test_op_mul.cpp
13	 * \brief 测试*运算符的功能，操作数都是tensor
14	 */
15	
16	#include "atvoss.h"
17	#include "example_common.h"
18	#include "utils/layout/shape.h"
19	
20	static constexpr int32_t MAX_DIM = 8;
21	
22	template <typename T1, typename T2>
23	struct MulConfig {
24	    struct MulCompute {
25	        template <template <typename> class Tensor>
26	        __host_aicore__ constexpr auto Compute() const
27	        {
28	            auto in1 = Atvoss::PlaceHolder<1, Tensor<T1>, Atvoss::ParamUsage::IN>();
29	            auto in2 = Atvoss::PlaceHolder<2, Tensor<T1>, Atvoss::ParamUsage::IN>();
30	            auto out = Atvoss::PlaceHolder<3, Tensor<T2>, Atvoss::ParamUsage::OUT>();
31	            return (out = in1 * in2);
32	        };
33	    };
34	
35	    using ArchTag = Atvoss::Arch::DAV_3510;
36	    using BlockOp = Atvoss::Ele::BlockBuilder<MulCompute, ArchTag>;
37	    using KernelOp = Atvoss::Ele::KernelBuilder<BlockOp>;
38	    using DeviceOp = Atvoss::DeviceAdapter<KernelOp>;
39	};
40	
41	template <typename T1, typename T2>
42	static void Run()
43	{
44	    // --- Step 1: ACL 初始化 ---
45	    CHECK_ACL_RET(aclInit(nullptr));
46	    auto finalizeGuard = ReleaseSource([]() { aclFinalize(); });
47	
48	    // --- Step 2: 设置 device ---
49	    const int32_t deviceId = 0;
50	    CHECK_ACL_RET(aclrtSetDevice(deviceId));
51	    auto deviceResetGuard = ReleaseSource([deviceId]() { aclrtResetDevice(deviceId); });
52	
53	    // --- Step 3: 创建 Context ---
54	    aclrtContext context = nullptr;
55	    CHECK_ACL_RET(aclrtCreateContext(&context, deviceId));
56	    auto contextDestroyGuard = ReleaseSource([context]() { aclrtDestroyContext(context); });
57	
58	    // --- Step 4: 创建 Stream ---
59	    aclrtStream stream = nullptr;
60	    CHECK_ACL_RET(aclrtCreateStream(&stream));
61	    auto streamDestroyGuard = ReleaseSource([stream]() { aclrtDestroyStream(stream); });
62	
63	    // --- Step 5: 分配设备内存 ---
64	    void* in1 = nullptr;
65	    CHECK_ACL_RET(aclrtMalloc(&in1, 8 * sizeof(T1), ACL_MEM_MALLOC_HUGE_FIRST));
66	    auto input1FreeGuard = ReleaseSource([in1]() { aclrtFree(in1); });
67	    T1* deviceIn1 = static_cast<T1*>(in1);
68	    void* in2 = nullptr;
69	    CHECK_ACL_RET(aclrtMalloc(&in2, 8 * sizeof(T1), ACL_MEM_MALLOC_HUGE_FIRST));
70	    auto input2FreeGuard = ReleaseSource([in2]() { aclrtFree(in2); });
71	    T1* deviceIn2 = static_cast<T1*>(in2);
72	    void* out = nullptr;
73	    CHECK_ACL_RET(aclrtMalloc(&out, 8 * sizeof(T2), ACL_MEM_MALLOC_HUGE_FIRST));
74	    auto outputFreeGuard = ReleaseSource([out]() { aclrtFree(out); });
75	    T2* deviceOutput = static_cast<T2*>(out);
76	
77	    // --- Step 6: Host -> Device 数据拷贝 ---
78	    std::vector<T1> hostInput1(8 * sizeof(T1), static_cast<T1>(3));
79	    CHECK_ACL_RET(aclrtMemcpy(deviceIn1, 8 * sizeof(T1), hostInput1.data(), 8 * sizeof(T1), ACL_MEMCPY_HOST_TO_DEVICE));
80	    std::vector<T1> hostInput2(8 * sizeof(T1), static_cast<T1>(4));
81	    CHECK_ACL_RET(aclrtMemcpy(deviceIn2, 8 * sizeof(T1), hostInput2.data(), 8 * sizeof(T1), ACL_MEMCPY_HOST_TO_DEVICE));
82	
83	    // --- Step 7: 构造 Args ---
84	    uint64_t shapeArray[MAX_DIM] = {8, 0, 0, 0, 0, 0, 0, 0};
85	    Atvoss::Tensor<T1> t1(deviceIn1, shapeArray, 1);
86	    Atvoss::Tensor<T1> t2(deviceIn2, shapeArray, 1);
87	    Atvoss::Tensor<T2> t3(deviceOutput, shapeArray, 1);
88	    auto arguments = Atvoss::ArgumentsBuilder{}.inputOutput(t1, t2, t3).build();
89	
90	    // --- Step 8: 执行算子 ---
91	    using DeviceOp = typename MulConfig<T1, T2>::DeviceOp;
92	    DeviceOp deviceOp;
93	    deviceOp.Run(arguments, stream);
94	
95	    // --- Step 9: 同步并拷回结果 ---
96	    CHECK_ACL_RET(aclrtSynchronizeStream(stream));
97	    std::vector<T2> hostOutput(8);
98	    CHECK_ACL_RET(
99	        aclrtMemcpy(hostOutput.data(), 8 * sizeof(T2), deviceOutput, 8 * sizeof(T2), ACL_MEMCPY_DEVICE_TO_HOST));
100	
101	    // --- Step 10: 验证结果 ---
102	    std::vector<T2> golden(8, 12);
103	    if (!VerifyResults(golden, hostOutput)) {
104	        std::cout << "Accuracy verification failed." << std::endl;
105	    } else {
106	        std::cout << "Accuracy verification passed." << std::endl;
107	    }
108	}
109	
110	int main(int argc, char const* argv[])
111	{
112	    Run<int32_t, int32_t>();
113	
114	    return 0;
115	}
