77	    T2* deviceOutput = static_cast<T2*>(out);
78	
79	    // --- Step 6: Host -> Device 数据拷贝 ---
80	    std::vector<T1> hostInput1(8 * sizeof(T1), static_cast<T1>(2));
81	    CHECK_ACL_RET(aclrtMemcpy(deviceIn1, 8 * sizeof(T1), hostInput1.data(), 8 * sizeof(T1), ACL_MEMCPY_HOST_TO_DEVICE));
82	    std::vector<T1> hostInput2(8 * sizeof(T1), static_cast<T1>(3));
83	    CHECK_ACL_RET(aclrtMemcpy(deviceIn2, 8 * sizeof(T1), hostInput2.data(), 8 * sizeof(T1), ACL_MEMCPY_HOST_TO_DEVICE));
84	
85	    // --- Step 7: 构造 Args ---
86	    uint64_t shapeArray[MAX_DIM] = {8, 0, 0, 0, 0, 0, 0, 0};
87	    Atvoss::Tensor<T1> t1(deviceIn1, shapeArray, 1);
88	    Atvoss::Tensor<T1> t2(deviceIn2, shapeArray, 1);
89	    Atvoss::Tensor<T2> t3(deviceOutput, shapeArray, 1);
90	    auto arguments = Atvoss::ArgumentsBuilder{}.inputOutput(t1, t2, t3).build();
91	
92	    // --- Step 8: 执行算子 ---
93	    using DeviceOp = typename ComputeTestConfig<T1, T2>::DeviceOp;
94	    DeviceOp deviceOp;
95	    deviceOp.Run(arguments, stream);
96	
97	    // --- Step 9: 同步并拷回结果 ---
98	    CHECK_ACL_RET(aclrtSynchronizeStream(stream));
99	    std::vector<T2> hostOutput(8);
100	    CHECK_ACL_RET(
101	        aclrtMemcpy(hostOutput.data(), 8 * sizeof(T2), deviceOutput, 8 * sizeof(T2), ACL_MEMCPY_DEVICE_TO_HOST));
102	
103	    // --- Step 10: 验证结果 ---
104	    std::vector<T2> golden(8, 6);
105	    if (!VerifyResults(golden, hostOutput)) {
106	        std::cout << "Accuracy verification failed." << std::endl;
107	    } else {
108	        std::cout << "Accuracy verification passed." << std::endl;
109	    }
110	}
